L000423	\paragraph{Effective Hamiltonian.} Let us outline some technical details of our derivation of the effective Hamiltonian for quasiparticles occupying Andreev bound states in superconducting junctions at sufficiently low voltages. We start from the general expression for the current through a single conducting channel derived in Ref.~\cite{KZ}
L000424	\begin{multline}
L000425	I(t) = i e\Sp \Bigl\{
L000426	(\tilde{\mathbb{S}}_n  + a \hat \tau_1 )^{-1} (h - a h a^+)(\tilde{\mathbb{S}}_n^+  + a^+ \hat \tau_1)^{-1}
L000427	\\\times
L000428	\tilde{\mathbb{S}}_n^+[\chi(t)]
L000429	\partial_{\chi} \tilde{\mathbb{S}}_n[\chi(t)]
L000430	\Bigr\},
L000431	\label{It}
L000432	\end{multline}
L000433	where the functions $a$ and $h$ are defined in the main text. The matrices $\tilde{\mathbb{S}}_n[\chi(t)]$ and $\hat \tau_1$ are given by
L000434	\begin{equation}
L000435	\tilde{\mathbb{S}}_n(\chi)
L000436	=
L000437	\begin{pmatrix}
L000438	V(\chi) & 0 \\
L000439	0 & V^*(\chi) \\
L000440	\end{pmatrix},
L000441	\quad
L000442	\hat  \tau_1
L000443	=
L000444	\begin{pmatrix}
L000445	0 & 0 & 1 & 0 \\
L000446	0 & 0 & 0 & 1 \\
L000447	1 & 0 & 0 & 0 \\
L000448	0 & 1 & 0 & 0 \\
L000449	\end{pmatrix},
L000450	\label{tS}
L000451	\end{equation}
L000452	where
L000453	\begin{equation}
L000454	V(\chi) =
L000455	\begin{pmatrix}
L000456	\sqrt{R} & -i\sqrt{D} e^{-i\chi/2} \\
L000457	-i\sqrt{D} e^{i\chi/2} & \sqrt{R}
L000458	\end{pmatrix}.
L000459	\end{equation}
L000460	
L000461	In Eq.~\eqref{It} and below all products are understood as convolutions in the time domain,
L000462	\begin{equation}
L000463	C=AB, \quad \Leftrightarrow \quad C(t,t') = \int A(t, \tilde t) B(\tilde t, t') d \tilde t.
L000464	\end{equation}
L000465	Provided an operator $A$ in the time representation is described by the kernel $A(t,t')$, the kernel of the operator $A^+$ reads $A^+(t', t)$. The inverse operator $B=A^{-1}$ has the kernel obeying the equation
L000466	\begin{equation}
L000467	B=A^{-1}, \quad \Leftrightarrow \quad \int d \tilde t B(t, \tilde t) A(\tilde t, t') = \delta(t - t').
L000468	\end{equation}
L000469	Below we will use the same notation for the operators both in time and energy representations related to each other as
L000470	\begin{equation}
L000471	A(t - t') = \int \dfrac{d \varepsilon}{ 2\pi} e^{-i\varepsilon(t-t')} A(\varepsilon).
L000472	\end{equation}
L000473	The choice of a particular representation will be clear from the context.
L000474	
L000475	Performing a unitary transformation with a time-independent matrix in Eq.~\eqref{It}
L000476	\begin{equation}
L000477	\tilde  W(\chi)
L000478	=
L000479	U^+ \tilde{\mathbb{S}}_n(\chi) \hat \tau_1 U,
L000480	\quad
L000481	U =
L000482	\dfrac{1}{2}
L000483	\begin{pmatrix}
L000484	1 & i & i & 1 \\
L000485	1 & i & -i & -1 \\
L000486	i & 1 & 1 & i \\
L000487	i & 1 & -1 & -i
L000488	\end{pmatrix}
L000489	\label{UWU}
L000490	\end{equation}
L000491	we arrive at Eq.~\eqref{T3}.
L000492	
L000493	Next we use the exact identity
L000494	\begin{multline}
L000495	\Biggl[
L000496	\begin{pmatrix}
L000497	W_o a^{-1} W_o^{-1} & 0
L000498	\\
L000499	0 & W_o a^{-1} W_o^{-1}
L000500	\end{pmatrix} \tilde W^+ + 1
L000501	\Biggr]
L000502	(\tilde W +  a)
L000503	\\=
L000504	-\dfrac{2}{|\Delta|}
L000505	\begin{pmatrix}
L000506	(\varepsilon - \mathcal{H}) & 0 \\
L000507	0 & (\varepsilon - \mathcal{H})
L000508	\end{pmatrix} ,
L000509	\label{inv22}
L000510	\end{multline}
L000511	where $\mathcal{H}$ is defined by Eq.~\eqref{Heff}. This identity can be verified directly by expanding both sides of Eq.~\eqref{inv22}, which immediately leads to the representation \eqref{inv2} for the inverse operator $(\tilde W+a)^{-1}$.
L000512	
L000513	Here we stress that all the operators below are understood in the time domain as integral operators with kernels depending on the time differences. Formally, the function $F(\varepsilon)$ denotes an operator whose kernel in the time representation is given by the Fourier transformation
L000514	\begin{equation}
L000515	F(t-t') = \int \frac{d\varepsilon}{2\pi}\, e^{-i\varepsilon(t-t')} F(\varepsilon).
L000516	\end{equation}
L000517	In this sense, the variable $\varepsilon$ and any expression built from it should be understood as a shorthand notation for the corresponding convolution operators in the time domain. For compactness, we use the same notation $F(\varepsilon)$ both for the Fourier space functions and associated operators.
L000518	
L000519	In order to proceed let us make use of the fact that in the low voltage limit the matrices $W_{d,o}$ are slowly varying functions of time. In this regime, we adopt a symbolic operator notation where the product $F(\varepsilon) f(t)$ implies a nonlocal operator acting on the function $f(t)$. With this convention, one can verify an approximate interchange rule
L000520	\begin{equation}
L000521	F(\varepsilon) f(t) \approx
L000522	f(t) F(\varepsilon) + i f'(t) F'(\varepsilon),
L000523	\label{inter}
L000524	\end{equation}
L000525	where $f(t)$ is a slowly varying function of time.
L000526	
L000527	Making use of the identities for the Andreev reflection amplitude $a(\varepsilon)$,
L000528	\begin{gather}
L000529	a'/a = - \dfrac{1}{|\Delta|} \dfrac{2 }{a - 1/a} = -\dfrac{1}{\sqrt{\varepsilon^2 - |\Delta|^2}},
L000530	\\
L000531	a'/a^2 =  \dfrac{1}{|\Delta|}
L000532	\left(1 + \dfrac{\varepsilon}{\sqrt{\varepsilon^2 - |\Delta|^2}}\right)
L000533	\end{gather}
L000534	and employing the interchange rule \eqref{inter}, we arrive at the expression for the effective Hamiltonian
L000535	\begin{multline}
L000536	\mathcal{H} \approx
L000537	|\Delta|W_d
L000538	+
L000539	\dfrac{i}{2}
L000540	W'_o W_o^{-1}
L000541	\\+
L000542	\dfrac{i}{2}
L000543	\Bigl[
L000544	|\Delta|W'_d
L000545	+
L000546	W'_o W_o^{-1}  (\varepsilon - |\Delta| W_d)
L000547	\Bigr]
L000548	\dfrac{1}{\sqrt{\varepsilon^2 - |\Delta|^2}}.
L000549	\label{Heff2}
L000550	\end{multline}
L000551	Within the same approximation, one can replace $\varepsilon$ in the expression for $\mathcal{H}$ by $|\Delta|W_d$. This immediately yields the effective Hamiltonian \eqref{Heff3}.
L000552	
