L000554	\paragraph{Time-dependent Landau--Zener amplitudes.}
L000555	Here we present some technical details of our evaluation of the time-dependent Landau--Zener amplitudes $r(t)$ and $d(t)$ for the whole time domain. In the limit $R\ll1$ and $|\chi-\pi|\ll 1$, the functions $\psi_{\pm}(t)$ can be written (in dimensionless units) as
L000556	\begin{widetext}
L000557	\begin{gather}
L000558	\psi_+(t)
L000559	=
L000560	\dfrac{
L000561	\begin{pmatrix}
L000562	\sqrt{s} \\
L000563	\sqrt{s + (\tau - \tau_0)^2/4} + (\tau - \tau_0)/2
L000564	\end{pmatrix}}{
L000565	\sqrt{2 \sqrt{s + (\tau - \tau_0)^2/4} \left[\sqrt{s + (\tau - \tau_0)^2/4} + (\tau - \tau_0)/2\right]}
L000566	}
L000567	\exp\left(
L000568	-i\dfrac{\pi}{4}
L000569	-i  \Phi(\tau)
L000570	\right) ,
L000571	\label{psippi}
L000572	\\
L000573	\psi_-(t)
L000574	=
L000575	\dfrac{
L000576	\begin{pmatrix}
L000577	\sqrt{s + (\tau - \tau_0)^2/4} + (\tau - \tau_0)/2
L000578	\\
L000579	-\sqrt{s}
L000580	\end{pmatrix}}{
L000581	\sqrt{2 \sqrt{s + (\tau - \tau_0)^2/4} \left[\sqrt{s + (\tau - \tau_0)^2/4} + (\tau - \tau_0)/2\right]}
L000582	}
L000583	\exp\left(
L000584	-i\dfrac{\pi}{4}
L000585	+i \Phi(\tau)
L000586	\right) ,
L000587	\label{psimpi}
L000588	\end{gather}
L000589	where we define
L000590	\begin{equation}
L000591	\tau_0 = \dfrac{1}{2}
L000592	\sqrt{\dfrac{\dot \chi}{|\Delta|}},
L000593	\quad
L000594	\Phi(\tau) =
L000595	\dfrac{1}{2}
L000596	(\tau + \tau_0)\sqrt{s + (\tau - \tau_0)^2/4}
L000597	-
L000598	\dfrac{1}{2} s \ln s
L000599	+
L000600	s \ln \left[
L000601	\sqrt{s + (\tau - \tau_0)^2/4} + (\tau - \tau_0)/2
L000602	\right].
L000603	\end{equation}
L000604	
L000605	The functions $\tilde \Psi_{\pm}(t)$ can be evaluated in the same limit using the exact solution of the Landau--Zener problem in terms of parabolic cylinder functions \cite{Z32,Iv23}. We obtain
L000606	\begin{equation}
L000607	\tilde\Psi_+(t) =
L000608	\dfrac{\sqrt{s}\Gamma(is)}{\sqrt{2\pi}}
L000609	\begin{pmatrix}
L000610	\sqrt{s} e^{i\pi/4}
L000611	\left[e^{\pi s/4}  D_{-is-1}(\tau e^{i\pi/4}) +  e^{-3\pi s/4} D_{-is-1}(\tau e^{-3i\pi/4})\right]
L000612	\\
L000613	e^{\pi s/4} D_{-is}(\tau e^{i\pi/4}) -  e^{-3\pi s/4} D_{-is}(\tau e^{-3i\pi/4})
L000614	\end{pmatrix}
L000615	\exp\left(
L000616	- i \dfrac{s}{2}\ln\dfrac{s}{e} - i \dfrac{\tau_0^2}{4}\right).
L000617	\label{Psippi}
L000618	\end{equation}
L000619	\end{widetext}
L000620	Direct analysis demonstrates that the functions $\psi_+(t)$ and $\tilde \Psi_+(t)$ defined in Eqs.~\eqref{psippi} and \eqref{Psippi} indeed have the same asymptotics in the region $\chi < \pi$ ($\tau \ll -1$). Employing these functions, one can immediately evaluate the Landau--Zener amplitudes $r(t)$ and $d(t)$ in terms of the parabolic cylinder functions,
L000621	\begin{gather}
L000622	r(t) = \psi_+^+(t)\tilde\Psi_+(t),
L000623	\quad
L000624	d(t) = \psi_+^+(t) \hat p_2 \tilde\Psi_+^*(t).
L000625	\label{rdeq}
L000626	\end{gather}
L000627	The functions $r(t)$ and $d(t)$ ~\eqref{rdeq} are substituted into Eq. (21) and the resulting dependencies $I(\chi )$ are displayed by dashed blue lines in Figs. 2-4.
